cd ~/.claude/projects/-home-ubuntu/
mkdir -p "$CLAUDE_JOB_DIR/tmp"
python3 - > "$CLAUDE_JOB_DIR/tmp/last100.txt" <<'EOF'
import json
f='1922c1ec-ec29-4fe4-a796-77c185b1f8e5.jsonl'
lines=open(f,encoding='utf-8',errors='replace').readlines()
tail=lines[-100:]
def clip(s,n=220):
    s=' '.join(str(s).split())
    return s if len(s)<=n else s[:n]+' …'
for i,line in enumerate(tail):
    try: d=json.loads(line)
    except Exception as e:
        print(f"[{i}] <解析失败>"); continue
    ts=(d.get('timestamp') or '')[11:19]
    t=d.get('type')
    if t=='summary':
        print(f"[{i}] {ts} SUMMARY: {clip(d.get('summary'),300)}\n"); continue
    m=d.get('message') or {}
    role=m.get('role',t)
    c=m.get('content')
    parts=[]
    if isinstance(c,str):
        parts.append(clip(c))
    elif isinstance(c,list):
        for x in c:
            if not isinstance(x,dict): continue
            ty=x.get('type')
            if ty=='text': parts.append('TEXT: '+clip(x.get('text')))
            elif ty=='thinking': parts.append('THINK: '+clip(x.get('thinking'),120))
            elif ty=='tool_use':
                inp=x.get('input',{}) or {}
                key=inp.get('command') or inp.get('file_path') or inp.get('pattern') or inp.get('description') or ''
                parts.append(f"TOOL[{x.get('name')}]: "+clip(key,180))
            elif ty=='tool_result':
                cc=x.get('content')
                if isinstance(cc,list): cc=' '.join(y.get('text','') for y in cc if isinstance(y,dict))
                parts.append('RESULT: '+clip(cc,150))
    if not parts: continue
    print(f"[{i}] {ts} {role}: " + ' | '.join(parts))
EOF
wc -l "$CLAUDE_JOB_DIR/tmp/last100.txt"; wc -c "$CLAUDE_JOB_DIR/tmp/last100.txt"

