1	/****************************************************************************
2	 * FOCUS AIoT - RGB565 → JPEG 编码 (core/rgb565_jpeg.c)
3	 *
4	 * 摄像头输出 RGB565, 云端 MiMo 识图需要 JPEG。
5	 * 本模块: RGB565 → RGB888 → TinyJPEG (Baseline JPEG) 编码。
6	 *
7	 * 基于 TinyJPEG (https://github.com/serge-rgb/TinyJPEG), public domain。
8	 ****************************************************************************/
9	
10	#define TJE_IMPLEMENTATION
11	#include "../third_party/tiny_jpeg.h"
12	
13	#include "rgb565_jpeg.h"
14	
15	#include <stdlib.h>
16	#include <string.h>
17	
18	/* ---- JPEG 输出收集 (内存回调) ---- */
19	typedef struct
20	{
21	  uint8_t *buf;    /* 输出缓冲区 */
22	  size_t   cap;    /* 容量 */
23	  size_t   used;   /* 已写字节 */
24	  int      overflowed;  /* 输出超出容量 (会截断, 上层需扩大缓冲) */
25	} jpeg_sink_t;
26	
27	/* 上传图降采样倍数 (1=原图, 2=320x240→160x120)。调大可显著减小 WiFi
28	 * 发送量 (base64 请求体), 但识别精度下降; 1 时请求体可达 100KB+。 */
29	#ifndef RGB565_JPEG_DOWNSCALE
30	#  define RGB565_JPEG_DOWNSCALE 2
31	#endif
32	
33	/* RGB888 转换暂存缓冲: 一次分配反复使用 (见 rgb565_to_jpeg 注释) */
34	static uint8_t *g_rgb_scratch;
35	static int      g_rgb_scratch_px;
36	
37	static void jpeg_write_cb(void *context, void *data, int size)
38	{
39	  jpeg_sink_t *sink = (jpeg_sink_t *)context;
40	
41	  if (sink->used + (size_t)size <= sink->cap)
42	    {
43	      memcpy(sink->buf + sink->used, data, (size_t)size);
44	      sink->used += (size_t)size;
45	    }
46	  else
47	    {
48	      /* 溢出: 丢弃并标记。静默截断会丢 JPEG 的 EOI 标记, 云端解码 400。 */
49	      sink->overflowed = 1;
50	    }
51	}
52	
53	/****************************************************************************
54	 * Name: rgb565_to_jpeg
55	 ****************************************************************************/
56	int rgb565_to_jpeg(const uint8_t *rgb565, int width, int height,
57	                   uint8_t *jpeg_out, size_t *jpeg_size)
58	{
59	  uint8_t *rgb;
60	  jpeg_sink_t sink;
61	  int ok;
62	  int n;
63	  int i;
64	  int out_w;
65	  int out_h;
66	
67	  if (rgb565 == NULL || jpeg_out == NULL || jpeg_size == NULL ||
68	      width <= 0 || height <= 0)
69	    {
70	      return -1;
71	    }
72	
73	  /* 降采样: 设备经 WiFi 上传 base64 图, 320x240 JPEG 常有 60~90KB,
74	   * base64 后 80~120KB —— 过大会把 WiFi 发送路径压垮 (真机实测
75	   * StoreProhibited 崩溃)。默认 2 倍降到 160x120, 请求体缩到 ~25KB。
76	   * 必须能整除且结果为 8 的倍数 (JPEG MCU 尺寸)。 */
77	  out_w = width  / RGB565_JPEG_DOWNSCALE;
78	  out_h = height / RGB565_JPEG_DOWNSCALE;
79	  if (out_w < 8 || out_h < 8 || (out_w & 7) != 0 || (out_h & 7) != 0)
80	    {
81	      return -1;
82	    }
83	
84	  /* RGB565 → RGB888 (3 通道, TinyJPEG 需要)。
85	   * 缓冲一次性分配并复用 (不每帧 malloc/free): 每帧上百 KB 的分配/释放
86	   * 会造成堆碎片, 严重时分配器会复用 CPU1 IDLE 栈所在的堆块, 导致崩溃。 */
87	  n = out_w * out_h;
88	  if (g_rgb_scratch == NULL || g_rgb_scratch_px < n)
89	    {
90	      free(g_rgb_scratch);
91	      g_rgb_scratch = malloc((size_t)n * 3);
92	      if (g_rgb_scratch == NULL)
93	        {
94	          g_rgb_scratch_px = 0;
95	          return -1;
96	        }
97	      g_rgb_scratch_px = n;
98	    }
99	  rgb = g_rgb_scratch;
100	
101	  /* 按 RGB565_JPEG_DOWNSCALE 块取样 (取每块左上角像素, 够用且快) */
102	  for (i = 0; i < n; i++)
103	    {
104	      int ox = i % out_w;
105	      int oy = i / out_w;
106	      size_t si = ((size_t)oy * RGB565_JPEG_DOWNSCALE * width +
107	                   (size_t)ox * RGB565_JPEG_DOWNSCALE);
108	      uint16_t p = (uint16_t)(rgb565[si * 2]) |
109	                   (uint16_t)(rgb565[si * 2 + 1]) << 8;
110	      uint8_t r5 = (uint8_t)((p >> 11) & 0x1F);
111	      uint8_t g6 = (uint8_t)((p >> 5) & 0x3F);
112	      uint8_t b5 = (uint8_t)(p & 0x1F);
113	
114	      rgb[i * 3]     = (uint8_t)((r5 << 3) | (r5 >> 2));   /* R */
115	      rgb[i * 3 + 1] = (uint8_t)((g6 << 2) | (g6 >> 4));   /* G */
116	      rgb[i * 3 + 2] = (uint8_t)((b5 << 3) | (b5 >> 2));   /* B */
117	    }
118	
119	  /* TinyJPEG 编码 (quality 2)。
120	   * 注意: 细节多的帧输出可能 > out_w*out_h, 调用方缓冲必须给足,
121	   * 否则截断丢 EOI 标记, 服务端解码 400。 */
122	  sink.buf        = jpeg_out;
123	  sink.cap        = *jpeg_size;
124	  sink.used       = 0;
125	  sink.overflowed = 0;
126	
127	  ok = tje_encode_with_func(jpeg_write_cb, &sink, 2,
128	                            out_w, out_h, 3, rgb);
129	
130	  /* 不 free: g_rgb_scratch 复用 (见上) */
131	
132	  if (!ok || sink.overflowed)
133	    {
134	      return -1;
135	    }
136	
137	  *jpeg_size = sink.used;
138	  return 0;
139	}
