/****************************************************************************
 * FOCUS AIoT - 摄像头抽象接口 (api/camera.h)
 *
 * 负责人: 张沐泽
 * 职责: 封装 OV2640 DVP 采集，对上层提供统一的帧输出。
 *
 * 冻结: camera_capture_frame() 签名、输出格式、外部变量名。
 ****************************************************************************/

#ifndef FOCUS_AIOT_API_CAMERA_H
#define FOCUS_AIOT_API_CAMERA_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- 公共接口 ---- */

/* 初始化 OV2640，配置 QVGA 输出。
 * 返回: 0=成功, 负值=错误码 (见 error.h) */
int  camera_init(void);

/* 采集一帧图像，存入 buf（调用方在 PSRAM 中分配，至少 50KB）。
 * size 输出实际字节数。
 * 阻塞上限 500ms，超时返回 FOCUS_ERR_TIMEOUT。
 * 返回: 0=成功 */
int  camera_capture_frame(uint8_t *buf, size_t *size);

/* 关闭摄像头，释放 DMA。 */
void camera_deinit(void);

/* 最近一帧 JPEG 数据指针和大小。
 * 由 camera_task 采集完成后更新，perception_task 读取。
 * 读取方不应写这两个变量。 */
extern uint8_t *camera_frame_buffer;
extern size_t   camera_frame_size;

#ifdef __cplusplus
}
#endif

#endif /* FOCUS_AIOT_API_CAMERA_H */

1	/****************************************************************************
2	 * FOCUS AIoT - 真实摄像头驱动 (hardware/camera_ov2640.c)
3	 *
4	 * 负责人: 张沐泽
5	 * 职责: 通过 V4L2 从内核 esp32s3_cam 驱动 (/dev/video0) 采集单帧 JPEG。
6	 *
7	 * 说明:
8	 *   - OV2640 传感器初始化由内核 esp32s3_cam 驱动完成, 本文件只走 V4L2。
9	 *   - QVGA 320x240 JPEG, 缓冲区由调用方在 PSRAM 分配 (≥50KB)。
10	 *
11	 * ⚠️ 上板核验: 设备节点名(/dev/video0)、像素格式(JPEG)、ioctl 序列
12	 *   需与内核 esp32s3_cam 驱动实际实现核对 (见 DEVELOPMENT_TASKS 的
13	 *   V4L2_BUF_TYPE_STILL_CAPTURE / VIDIOC_TAKEPICT 单帧模式)。
14	 ****************************************************************************/
15	
16	#include "../api/camera.h"
17	#include "../api/error.h"
18	
19	#include <nuttx/config.h>
20	
21	#include <fcntl.h>
22	#include <poll.h>
23	#include <sys/ioctl.h>
24	#include <sys/videoio.h>
25	
26	#include <errno.h>
27	#include <stdint.h>
28	#include <stdio.h>
29	#include <stdlib.h>
30	#include <string.h>
31	#include <unistd.h>
32	
33	#define CAMERA_DEV      "/dev/video0"
34	#define CAMERA_WIDTH    320
35	#define CAMERA_HEIGHT   240
36	/* 内核 esp32s3_cam 驱动每轮 STREAMON 只采 1 帧就停 (ISR 置 capturing=false)。
37	 * V4L2 RING 判据是 vbuf_top != vbuf_next 才算有数据, 因此 BUFCOUNT 必须 ≥2
38	 * (=1 时自环, DQBUF 永久阻塞)。
39	 * 但 ≥2 时未消费的缓冲容器会残留在 RING 队列, 下次 QBUF 拿不到容器
40	 * 返回 -ENOMEM。解决: 每轮采集前用 REQBUFS 换一次 count 强制重建容器链
41	 * (见 camera_capture_frame)。 */
42	#define CAMERA_BUFCOUNT 2
43	#define CAMERA_BUFSIZE  (CAMERA_WIDTH * CAMERA_HEIGHT * 2)  /* RGB565 全尺寸 */
44	#define CAMERA_FRAME_TIMEOUT_MS 500   /* 单帧采集超时上限 */
45	
46	/* ⚠️ 真机核验 (2026-08-19): esp32s3_cam 驱动实际配置 QVGA RGB565
47	 * (即使 S_FMT 请求 JPEG 也回显 JPEG 但传感器输出 RGB565)。
48	 * 采集必须用 RGB565 + V4L2_BUF_MODE_RING (设备验证成功的模式)。
49	 * JPEG 输出留给感知层用 STILL_CAPTURE/TAKEPICT 路径。 */
50	
51	/* 最近一帧 (camera_task 采集后更新, perception 读取) */
52	uint8_t *camera_frame_buffer = NULL;
53	size_t   camera_frame_size   = 0;
54	
55	static int g_camera_fd = -1;
56	static uint8_t *g_cam_buf2 = NULL;  /* 第 2 个 RING 缓冲 (内部分配) */
57	
58	/****************************************************************************
59	 * Name: camera_init
60	 ****************************************************************************/
61	int camera_init(void)
62	{
63	  struct v4l2_format fmt;
64	  struct v4l2_requestbuffers req;
65	
66	  g_camera_fd = open(CAMERA_DEV, O_RDWR);
67	  if (g_camera_fd < 0)
68	    {
69	      return FOCUS_ERR_HW_NOTREADY;
70	    }
71	
72	  /* 设置 QVGA RGB565 输出 (匹配驱动实际, RING 模式可采帧) */
73	  memset(&fmt, 0, sizeof(fmt));
74	  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
75	  fmt.fmt.pix.width = CAMERA_WIDTH;
76	  fmt.fmt.pix.height = CAMERA_HEIGHT;
77	  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_RGB565;
78	  fmt.fmt.pix.field = V4L2_FIELD_NONE;
79	  if (ioctl(g_camera_fd, VIDIOC_S_FMT, (unsigned long)&fmt) < 0)
80	    {
81	      printf("[camera] S_FMT FAILED errno=%d\n", errno);
82	      close(g_camera_fd);
83	      g_camera_fd = -1;
84	      return FOCUS_ERR_HW_NOTREADY;
85	    }
86	
87	  /* 请求用户指针缓冲区, RING 模式 (驱动循环填充, 设备验证成功) */
88	  memset(&req, 0, sizeof(req));
89	  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
90	  req.memory = V4L2_MEMORY_USERPTR;
91	  req.count = CAMERA_BUFCOUNT;
92	  req.mode  = V4L2_BUF_MODE_RING;
93	  if (ioctl(g_camera_fd, VIDIOC_REQBUFS, (unsigned long)&req) < 0)
94	    {
95	      printf("[camera] REQBUFS FAILED errno=%d\n", errno);
96	      close(g_camera_fd);
97	      g_camera_fd = -1;
98	      return FOCUS_ERR_HW_NOTREADY;
99	    }
100	
101	  /* RING 模式需全部缓冲入队, 分配第 2 缓冲 */
102	  g_cam_buf2 = malloc(CAMERA_BUFSIZE);
103	  if (g_cam_buf2 == NULL)
104	    {
105	      printf("[camera] 第 2 缓冲分配失败\n");
106	      close(g_camera_fd);
107	      g_camera_fd = -1;
108	      return FOCUS_ERR_HW_NOTREADY;
109	    }
110	
111	  return FOCUS_OK;
112	}
113	
114	/****************************************************************************
115	 * Name: camera_capture_frame
116	 *
117	 * 采一帧 JPEG 到 buf。阻塞上限 500ms。
118	 ****************************************************************************/
119	int camera_capture_frame(uint8_t *buf, size_t *size)
120	{
121	  struct v4l2_buffer vbuf;
122	  struct v4l2_requestbuffers req;
123	  struct pollfd pfd;
124	  int type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
125	  int pr;
126	
127	  if (g_camera_fd < 0 || buf == NULL || size == NULL)
128	    {
129	      return FOCUS_ERR_HW_NOTREADY;
130	    }
131	
132	  /* 重置 RING 缓冲链: 驱动每轮只采 1 帧, 未消费的缓冲容器残留在队列,
133	   * 下次 QBUF 拿不到容器返回 -ENOMEM。REQBUFS 换一次 count 触发
134	   * video_framebuff_realloc_container → init_buf_chain 重建 (全部回空闲)。 */
135	  {
136	    int i;
137	    memset(&req, 0, sizeof(req));
138	    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
139	    req.memory = V4L2_MEMORY_USERPTR;
140	    req.mode  = V4L2_BUF_MODE_RING;
141	    req.count = CAMERA_BUFCOUNT + 1;   /* 先换计数 → 强制重建容器链 */
142	    ioctl(g_camera_fd, VIDIOC_REQBUFS, (unsigned long)&req);
143	    req.count = CAMERA_BUFCOUNT;       /* 恢复实际缓冲数 */
144	    ioctl(g_camera_fd, VIDIOC_REQBUFS, (unsigned long)&req);
145	
146	    /* 入队全部缓冲 (RING 模式需环完整, 否则 DQBUF 阻塞) */
147	    for (i = 0; i < CAMERA_BUFCOUNT; i++)
148	      {
149	        memset(&vbuf, 0, sizeof(vbuf));
150	        vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
151	        vbuf.memory = V4L2_MEMORY_USERPTR;
152	        vbuf.index = i;
153	        vbuf.m.userptr = (unsigned long)((i == 0) ? buf : g_cam_buf2);
154	        vbuf.length = CAMERA_BUFSIZE;
155	        if (ioctl(g_camera_fd, VIDIOC_QBUF, (unsigned long)&vbuf) < 0)
156	          {
157	            return FOCUS_ERR_IO;
158	          }
159	      }
160	  }
161	
162	  /* 开启流 (若已开启会返回 EBUSY, 忽略) */
163	  ioctl(g_camera_fd, VIDIOC_STREAMON, (unsigned long)&type);
164	
165	  /* poll 等待帧可用, 防止驱动异常时 DQBUF 永久阻塞 */
166	  pfd.fd = g_camera_fd;
167	  pfd.events = POLLIN;
168	  pr = poll(&pfd, 1, CAMERA_FRAME_TIMEOUT_MS);
169	  if (pr <= 0)
170	    {
171	      ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
172	      return FOCUS_ERR_TIMEOUT;
173	    }
174	
175	  /* 取一帧 */
176	  memset(&vbuf, 0, sizeof(vbuf));
177	  vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
178	  vbuf.memory = V4L2_MEMORY_USERPTR;
179	  if (ioctl(g_camera_fd, VIDIOC_DQBUF, (unsigned long)&vbuf) < 0)
180	    {
181	      printf("[camera] DQBUF FAILED errno=%d\n", errno);
182	      ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
183	      return FOCUS_ERR_TIMEOUT;
184	    }
185	
186	  /* 停流复位, 供下一次采集重新 STREAMON (驱动为单帧模式) */
187	  ioctl(g_camera_fd, VIDIOC_STREAMOFF, (unsigned long)&type);
188	
189	  *size = vbuf.bytesused;
190	  camera_frame_buffer = buf;
191	  camera_frame_size   = vbuf.bytesused;
192	
193	  return FOCUS_OK;
194	}
