198	 ****************************************************************************/
199	void camera_deinit(void)
200	{
201	  if (g_camera_fd >= 0)
202	    {
203	      close(g_camera_fd);
204	      g_camera_fd = -1;
205	    }
206	  if (g_cam_buf2 != NULL)
207	    {
208	      free(g_cam_buf2);
209	      g_cam_buf2 = NULL;
210	    }
211	  camera_frame_buffer = NULL;
212	  camera_frame_size   = 0;
213	}
