214	/* ==================== 主入口 ==================== */
215	
216	int main(int argc, char *argv[])
217	{
218	    if (argc > 1)
219	    {
220	        if (strcmp(argv[1], "hwbutton") == 0) return hw_test_button();
221	        if (strcmp(argv[1], "hwaudio") == 0)  return hw_test_audio();
222	        if (strcmp(argv[1], "hwcamera") == 0) return hw_test_camera();
223	        if (strcmp(argv[1], "hwwifi") == 0)   return hw_test_wifi(argc, argv);
224	        printf("未知命令: %s\n", argv[1]);
225	        printf("用法: hello_app [hwbutton|hwaudio|hwcamera|hwwifi <ssid> <pass>]\n");
226	        return 1;
227	    }
228	
229	    printf("\n");
230	    printf("==================================================\n");
231	    printf("  FOCUS AIoT v0.3 (真实硬件驱动)\n");
232	    printf("  板卡: ESP32-S3-EYE / openvela\n");
233	    printf("==================================================\n");
234	    printf("  模块状态:\n");
235	    printf("    state_machine  - 真实 FSM (core/state_machine.c)\n");
236	    printf("    ui             - 郭黄亦昕 (已集成)\n");
237	    printf("    behavior       - 赵思涵时序引擎\n");
238	    printf("    button/audio/camera/wifi - 张沐泽真实驱动\n");
239	    printf("    perception     - 周礼航感知 (mock 或真实识图服务)\n");
240	    printf("  子命令: hello_app hwbutton|hwaudio|hwcamera|hwwifi <ssid> <pass>\n");
241	    printf("==================================================\n\n");
242	
243	    /* ---- 模块初始化 ---- */
244	    init_modules();
245	    state_machine_init();
246	
247	    /* ---- 摄像头/感知帧缓冲 (PSRAM heap, 主循环复用) ---- */
248	    {
249	        uint8_t *frame = malloc(320 * 240 * 2);   /* RGB565 帧 */
250	        /* JPEG 输出: 必须 ≥ 3×帧大小。TinyJPEG quality=2 细节多时
251	         * 输出可超 width*height (实测噪声帧约 2.8×), 太小会截断丢
252	         * EOI 标记, MiMo 解码 400。 */
253	        uint8_t *jpeg_buf = malloc(320 * 240 * 3);
254	        observation_t obs;
255	        int frame_tick = 0;
256	        device_status_t st = DEVICE_IDLE;          /* 当前设备状态 (采集门控) */
257	        device_status_t prev_status = DEVICE_IDLE; /* 上一 tick 状态, 检测"刚进入 MONITORING" */
258	
259	        memset(&obs, 0, sizeof(obs));
260	        if (frame == NULL || jpeg_buf == NULL)
261	        {
262	            printf("[core] 帧缓冲分配失败, 感知暂停\n");
263	        }
264	
265	        printf("[core] 进入主循环: 状态机 @10Hz + 感知 @5s/帧 (仅 MONITORING 采集)...\n");
266	        printf("[core] 真实按键: 长按进模式选择, 短按开始, 超长按停止\n\n");
267	
268	        /* ---- 主循环: state_machine + 感知驱动 ---- */
269	        for (;;)
270	        {
271	            state_machine_tick();   /* 内部 behavior_analyze 消费感知历史 */
272	
273	            /* 采集门控: 仅 DEVICE_MONITORING 采帧喂感知。
274	             * IDLE/MODE_SELECT/REPORT 不采集 → 一进 hello_app 不再莫名识图、
275	             * 模式选择界面不被识图延迟拖累、超长按停止后立即停采。 */
276	            st = state_machine_get_status();
277	            if (st == DEVICE_MONITORING && prev_status != DEVICE_MONITORING)
278	            {
279	                frame_tick = 49;  /* 刚确认模式: 下一 tick (~100ms) 立即采首帧 */
280	            }
281	
282	            /* 一局结束 (进入 REPORT): 把统计上传中继, 由中继调 MiMo 生成
283	             * 学习建议并存入网页报告 (/report 页)。设备屏只提示看网页。
284	             * 放在主循环而非 state_machine_tick 内, 因为 HTTP 会阻塞数秒,
285	             * 而 tick 要求 20ms 内返回。 */
286	            if (st == DEVICE_REPORT && prev_status != DEVICE_REPORT)
287	            {
288	                session_report_t rep;
289	                session_stats_t st_copy;
290	
291	                memset(&rep, 0, sizeof(rep));
292	                st_copy = *state_machine_get_stats();
293	                rep.stats = st_copy;
294	                state_machine_get_distraction_by_type(rep.distraction_by_type);
295	                mimo_get_advice(&rep.stats, rep.distraction_by_type,
296	                                rep.advice, sizeof(rep.advice));
297	            }
298	
299	            prev_status = st;
300	
301	            /* 每 50 tick (5s) 采一帧喂感知, 更新 history 供行为引擎 */
302	            if (++frame_tick >= 50)
303	            {
304	                frame_tick = 0;
305	                if (st != DEVICE_MONITORING)
306	                {
307	                    continue;  /* 非监测状态不采集 */
308	                }
309	                /* 摄像头采集 RGB565 → 转 JPEG → 识图。
310	                 * 这里恒定走**真实采集与编码** (演示/联调时能证明视觉链路是真
311	                 * 在工作的: 串口会打印真实的采集字节数与 JPEG 大小)。
312	                 * 是否真的调云端由 perception 内部的 PERCEPTION_MOCK 决定:
313	                 * mock 模式下 perception_process 返回预设 observation 且不联网,
314	                 * 因此不会触发 WiFi 发送路径上的平台级崩溃。 */
315	                if (frame != NULL && jpeg_buf != NULL)
316	                {
317	                    static unsigned cap_seq = 0;
318	                    size_t fsize = 0;
319	                    size_t jpeg_size = 320 * 240 * 3;
320	                    int cret;
321	                    int pret;
322	
323	                    /* 每次采集都在串口打点, 便于真机核对采集/识图节奏 */
324	                    printf("[cam] #%u 尝试采集...\n", ++cap_seq);
325	                    cret = camera_capture_frame(frame, &fsize);
326	                    if (cret == FOCUS_OK && fsize > 0)
327	                    {
328	                        printf("[cam] #%u 采集OK %uB -> 转JPEG...\n",
329	                               cap_seq, (unsigned)fsize);
330	                        if (rgb565_to_jpeg(frame, 320, 240,
331	                                           jpeg_buf, &jpeg_size) == 0)
332	                        {
333	                            printf("[cam] #%u JPEG %uB -> 识图...\n",
334	                                   cap_seq, (unsigned)jpeg_size);
335	                            pret = perception_process(jpeg_buf, jpeg_size, &obs);
336	                            printf("[cam] #%u 识图返回=%d person=%d phone=%d "
337	                                   "pitch=%.1f motion=%.2f conf=%.2f\n",
338	                                   cap_seq, pret,
339	                                   (int)obs.person_present,
340	                                   (int)obs.phone_detected,
341	                                   obs.head_pitch,
342	                                   obs.hand_motion_score,
343	                                   obs.confidence);
344	                        }
345	                        else
346	                        {
347	                            printf("[cam] #%u JPEG 编码失败\n", cap_seq);
348	                        }
349	                    }
350	                    else
351	                    {
352	                        printf("[cam] #%u 采集失败 ret=%d errno=%d\n",
353	                               cap_seq, cret, errno);
354	                    }
355	                }
356	            }
357	
358	            usleep(100 * 1000);  /* 100ms = 10Hz */
359	        }
360	    }
361	
362	    return EXIT_SUCCESS;
363	}
