206	static void frame_complete_worker(void *arg)
207	{
208	  struct esp32s3_cam_s *priv = (struct esp32s3_cam_s *)arg;
209	
210	  if (priv->cb == NULL || priv->fb == NULL)
211	    {
212	      return;
213	    }
214	
215	  up_invalidate_dcache((uintptr_t)priv->fb,
216	                       (uintptr_t)priv->fb + priv->fb_size);
217	
218	  if (priv->v4l2_buf != NULL)
219	    {
220	      memcpy(priv->v4l2_buf, priv->fb, priv->fb_size);
221	    }
222	
223	  priv->cb(0, priv->fb_size, &priv->frame_ts, priv->cb_arg);
224	}
