226	/****************************************************************************
227	 * Name: cam_interrupt
228	 *
229	 * Description:
230	 *   CAM VSYNC interrupt handler. Called when a frame is complete.
231	 *
232	 ****************************************************************************/
233	
234	static int IRAM_ATTR cam_interrupt(int irq, void *context, void *arg)
235	{
236	  struct esp32s3_cam_s *priv = (struct esp32s3_cam_s *)arg;
237	  uint32_t status = getreg32(LCD_CAM_LC_DMA_INT_ST_REG);
238	
239	  if (status & LCD_CAM_CAM_VSYNC_INT_ST_M)
240	    {
241	      /* Clear interrupt */
242	
243	      putreg32(LCD_CAM_CAM_VSYNC_INT_CLR_M,
244	               LCD_CAM_LC_DMA_INT_CLR_REG);
245	
246	      if (priv->capturing)
247	        {
248	          priv->vsync_cnt++;
249	
250	          /* First VSYNC = start of frame (DMA begins filling buffer).
251	           * Second VSYNC = end of frame (buffer is complete).
252	           */
253	
254	          if (priv->vsync_cnt == 1)
255	            {
256	              /* Frame capture just started, DMA is now receiving data.
257	               * Nothing to do here — wait for next VSYNC.
258	               */
259	            }
260	          else if (priv->vsync_cnt >= 2 && priv->cb)
261	            {
262	              uint32_t regval;
263	
264	              regval = getreg32(LCD_CAM_CAM_CTRL1_REG);
265	              regval &= ~LCD_CAM_CAM_START_M;
266	              putreg32(regval, LCD_CAM_CAM_CTRL1_REG);
267	
268	              regval = getreg32(LCD_CAM_CAM_CTRL_REG);
269	              regval |= LCD_CAM_CAM_UPDATE_REG_M;
270	              putreg32(regval, LCD_CAM_CAM_CTRL_REG);
271	
272	              SET_GDMA_CH_BITS(DMA_IN_LINK_CH0_REG,
273	                               priv->dma_channel,
274	                               DMA_INLINK_STOP_CH0_M);
275	
276	              /* Bounded wait for DMA to park */
277	
278	              for (int tries = 1000; tries > 0; tries--)
