169	static void esp32s3_cam_setup_dma(struct esp32s3_cam_s *priv)
170	{
171	  uint8_t *pbuf = priv->fb;
172	  uint32_t remaining = priv->fb_alloc;
173	  uint32_t total_desc;
174	  uint32_t i;
175	
176	  total_desc = (remaining + ESP32S3_CAM_DMA_BUFLEN - 1) /
177	               ESP32S3_CAM_DMA_BUFLEN;
178	
179	  for (i = 0; i < total_desc && i < ESP32S3_CAM_DMADESC_NUM; i++)
180	    {
181	      uint32_t data_len;
182	      uint32_t buf_len;
183	
184	      data_len = remaining > ESP32S3_CAM_DMA_BUFLEN ?
185	                 ESP32S3_CAM_DMA_BUFLEN : remaining;
186	      buf_len = (data_len + 63) & ~63;
187	
188	      priv->dmadesc[i].ctrl = ESP32S3_DMA_CTRL_OWN |
189	          (buf_len << ESP32S3_DMA_CTRL_BUFLEN_S);
190	      priv->dmadesc[i].pbuf = pbuf;
191	
192	      if (i < total_desc - 1)
193	        {
194	          priv->dmadesc[i].next = &priv->dmadesc[i + 1];
195	        }
196	      else
197	        {
198	          priv->dmadesc[i].next = NULL;
199	        }
200	
201	      pbuf += data_len;
202	      remaining -= data_len;
203	    }
204	}

=== reset_channel 实现 ===
 * Name: esp32s3_dma_reset_channel
 *
 * Description:
 *   Reset DMA channel by toggling the reset bit in CONF0 register.
 *
 * Input Parameters:
 *   chan - DMA channel
 *   tx   - true: TX mode; false: RX mode
 *
 * Returned Value:
 *   None.
 *
 ****************************************************************************/

void esp32s3_dma_reset_channel(int chan, bool tx)
{
  if (tx)
    {
      SET_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUT_RST_CH0_M);
      CLR_GDMA_CH_BITS(DMA_OUT_CONF0_CH0_REG, chan, DMA_OUT_RST_CH0_M);
    }
  else
    {
      SET_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_IN_RST_CH0_M);
      CLR_GDMA_CH_BITS(DMA_IN_CONF0_CH0_REG, chan, DMA_IN_RST_CH0_M);
    }
}

